"""Author Phase 2 review artifacts only; Phase 1 evidence and production are read-only."""
from pathlib import Path
import collections, hashlib, json, re, subprocess
ROOT=Path(__file__).resolve().parents[4]
OUT=Path(__file__).resolve().parent
AUDIT=OUT.parent
DOCS=ROOT/'docs/plans/isc2-cc-2026'
def load(name):return json.loads((AUDIT/name).read_text(encoding='utf-8'))
def save(name,data):(OUT/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
BACKLOG={r['id']:r for r in load('prioritized-backlog.json')}
MATRIX={r['anchor']:r for r in load('coverage-matrix.json')}
ISSUES={r['id']:r for r in load('accuracy-findings.json')}
MEDIA={r['id']:r for r in load('media-planning-manifest.json')}
INPUTS={r['id']:r for r in json.loads((OUT/'current-target-excerpts.json').read_text(encoding='utf-8'))}
DECISIONS={}
def record(id,decision,current,gap,change,en='',th='',reason='',constraints='',preserve='',severity=None,refs=None,deps=None,effort='30–60 minutes including bilingual and summary reconciliation'):
    b=BACKLOG.get(id,{})
    target=b.get('target',MEDIA.get(id,{}).get('target',''))
    m=MATRIX.get(target)
    category={'CORRECT ACADEMIC ERROR':'Academic correction','EXPAND EXPLANATION':'Explanation','ADD PRACTICAL EXAMPLE':'Practical example','REQUIRES VERIFICATION':'Open lead','ADD DIAGRAM':'Visual/media','ADD REAL-WORLD IMAGE':'Visual/media','ADD ANIMATION / INTERACTIVE VISUAL':'Visual/media'}.get(b.get('primaryClassification'),'Legacy/duplicate proposal')
    d=b.get('domain',MEDIA.get(id,{}).get('domain',0))
    targets=[{'path':m['readingPath'],'anchor':target,'startLine':m['line'],'endLine':m['endLine']}] if m else [{'path':f'content/isc2-cc-2026/reading/domain-{n}.md','anchor':'approved changed passages only'} for n in range(1,6)]
    DECISIONS[id]={'id':id,'domain':d,'officialObjective':'.'.join(target.split('-')[1:3]) if target.startswith('topic-') else 'Cross-domain acceptance / current-outline application','category':category,'auditClassification':b.get('primaryClassification',MEDIA.get(id,{}).get('primaryClassification')),'decision':decision,'currentLearnerExperience':current,'genuineGap':gap,'smallestUsefulChange':change,'sample':{'en':en,'th':th},'reason':reason,'academicConstraints':constraints or 'Stay at the stated CC concept; label hypothetical conditions and avoid unconditional guarantees.','preserveExisting':preserve or 'Retain current definitions, useful comparisons, anchors and existing lesson visuals; change only the identified claim/example.','targets':targets,'supportingSources':(refs or [])+b.get('sources',[]),'dependencies':deps or [],'estimatedEffort':effort,'severity':severity or b.get('priority','P3'),'implementationAuthorized':False,'userApprovalRequired':True,'acceptanceCriteria':['Only the named target and accepted representations change; existing anchors remain intact.','Thai and English convey the same actor, condition, quantity and limitation.','Check repeated Reading summaries/scenarios and changed diagram labels; do not edit Learning Slides, Vocabulary or Question Banks.','Compare against cited primary reference and the exact current passage; do not expand into vendor setup or algorithm internals.'],'evidence':{'readingExcerpt':f'current-target-excerpts.json#{id}' if id in INPUTS else None,'phase1Record':id if id in BACKLOG else None}}
    if id in ISSUES:DECISIONS[id]['reportedAcademicEvidence']=ISSUES[id]

# All eleven claimed correction groups are independently dispositioned, not assumed wholesale wrong.
record('ACC-D1-01','APPROVE WITH REVISION','Privacy table contrasts encryption with consent and transparency; line 320 implies absent consent is enough to establish a violation.','The lawful basis is unspecified; transparency and consent are different questions.','Replace the blanket consent inference with an applicable-law/basis qualifier; retain the privacy-versus-confidentiality distinction.','Encryption restricts access. Privacy also requires an appropriate purpose and lawful basis; consent is one possible basis under the GDPR.','การเข้ารหัสจำกัดการเข้าถึง ส่วน Privacy ยังต้องพิจารณาวัตถุประสงค์และฐานกฎหมายที่เหมาะสม โดยความยินยอมเป็นฐานหนึ่งตาม GDPR','The EDPB directly supports the scope correction; it does not establish Thai retention periods or resolve every PDPA example.','Do not say all personal-data processing requires consent or that no-consent processing is automatically unlawful.','Keep the existing roles, inventory and qualified erasure explanation.',severity='P1',refs=['https://www.edpb.europa.eu/topics/key-gdpr-concepts/legal-basis_en — General information'])
record('ACC-D2-01','APPROVE WITH REVISION','RTO/RPO prose and the 17:00 example correctly separate targets; line 259 nevertheless equates exceeding the planning bound with inability to survive.','One categorical conclusion contradicts the earlier business-impact definition. The backup label may be a hypothetical observation rather than an error.','Correct line 259; label the equation a simplified planning model. Distinguish an assumed backup from a target boundary without claiming the existing backup timestamp is intrinsically invalid.','Exceeding MTD means the outage exceeds the business tolerance defined for this case; it does not always mean the organization cannot survive.','การหยุดชะงักเกิน MTD หมายถึงเกินขอบเขตที่ธุรกิจยอมรับในกรณีนี้ ไม่ได้หมายความว่าองค์กรจะอยู่รอดไม่ได้เสมอไป','NIST 800-34 section 3.2.1 supports impact/tolerance terminology. Preserve the correct 16:30/17:00/18:00 example and its units.','Do not present RTO+WRT as a universal sequential law; use explicitly defined intervals.',severity='P1')
record('ACC-D2-02','APPROVE','The notes explicitly allow count, rate, ratio and mean; the embedded graphic calls METRIC a Quantifiable Raw Value.','This is a prose/graphic inconsistency, not a missing metrics chapter.','Replace the raw-only graphic label with defined measurable value; qualify dashboard update time in the existing diagram and cues.','A metric can be a count, percentage, ratio or average with a defined scope and period.','Metric อาจเป็นจำนวน ร้อยละ อัตราส่วน หรือค่าเฉลี่ย โดยต้องกำหนดขอบเขตและช่วงเวลาที่วัด','The correction is ready and supported both by the notes and NIST measurement examples.','Do not create a second measurement hierarchy or assume every dashboard is real time.',severity='P1',refs=['js/core/diagram-generator.js:1775 — exact contradictory label'])
record('ACC-D3-01','APPROVE WITH REVISION','The mover case uses Domain Admin for Helpdesk and mandates removal of all old rights before every new grant.','Universal removal order and automatic SoD violation are not established; the privileged grant may be an intentionally bad example.','Use task-scoped helpdesk rights, or explicitly label Domain Admin excessive under the example policy. Remove obsolete/conflicting rights, retain justified common rights and verify the controlled transition.','After the transfer, retain justified common access, remove obsolete Finance rights and grant only the approved Helpdesk tasks.','เมื่อย้ายงาน ให้คงสิทธิ์ส่วนกลางที่ยังจำเป็น ถอนสิทธิ์ Finance ที่หมดความจำเป็น และให้เฉพาะงาน Helpdesk ที่ได้รับอนุมัติ','AC-6 and PS-5 support justified task access and policy-defined transitions. Do not recast every combined permission set as an SoD violation.','State the example policy; distinguish an insecure scenario from a recommendation to grant Domain Admin.',severity='P0',refs=['https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.800-53r5.pdf — AC-6 and PS-5'])
record('ACC-D4-02','APPROVE WITH REVISION','TCP is correctly described as reliable, sequenced and retransmitting, but its complete-data wording and speed comparison read as unconditional.','The missing boundary is connection failure and application completion, not an absence of TCP reliability.','Retain reliable ordered byte-stream terminology. Add a concise failure/application boundary and qualify speed comparisons; do not rewrite TCP as unreliable.','TCP provides an ordered, reliable byte stream, but a connection can fail. Receiving bytes does not prove the application completed the requested transaction.','TCP ให้บริการข้อมูลไบต์แบบเรียงลำดับและเชื่อถือได้ แต่การเชื่อมต่ออาจล้มเหลว การรับไบต์ไม่ได้พิสูจน์ว่าแอปทำธุรกรรมที่ร้องขอสำเร็จ','RFC 9293 supports both reliability and connection failure. This is an overstatement correction, not rejection of the core transport definition.','TCP reliability is not cryptographic integrity, secrecy or business-transaction confirmation.',severity='P1')
record('ACC-D4-03','APPROVE WITH REVISION','Segmentation is defined with enforcement, but benefit bullets promise containment and automatic compliance-scope reduction.','Allowed paths, compromised control points and policy effectiveness are missing conditions.','Replace certainty with risk/reachability reduction; retain the architecture and state compliance scoping requires validated applicable conditions.','Segmentation can limit lateral movement when boundaries are enforced and tested; it does not guarantee that compromise stays in one segment.','Segmentation ช่วยจำกัดการเคลื่อนที่ข้ามระบบเมื่อบังคับใช้และทดสอบขอบเขตแล้ว แต่ไม่รับประกันว่าเหตุบุกรุกจะอยู่ในเซกเมนต์เดียว','CISA and NIST support limiting exposure rather than an unconditional containment guarantee.','A flat network does not alone prove every host is compromised; a VLAN name alone is not an enforcement policy.',severity='P0',refs=['https://www.cisa.gov/sites/default/files/2025-07/ZT-Microsegmentation-Guidance-Part-One_508c.pdf — scope and lateral-movement purpose'])
record('ACC-D5-01','APPROVE','The generic signature recipe encrypts a digest using the sender private key and decrypts it using the public key.','That is not a scheme-independent signature model.','Replace those two operation descriptions with signing/verification, using trusted key association and signed content. Retain hashing and password-storage sections; do not add algorithm mathematics.','The signer creates a signature using the private key. The verifier checks the content and signature using the corresponding trusted public key; signing does not hide the content.','ผู้ลงนามสร้างลายเซ็นด้วยกุญแจส่วนตัว ผู้ตรวจใช้กุญแจสาธารณะที่สัมพันธ์กันและเชื่อถือได้ตรวจเนื้อหากับลายเซ็น การลงนามไม่ได้ซ่อนเนื้อหา','FIPS 186-5 sections 3.2–3.3 directly distinguish generation and verification.','Do not promise proof of human intent or harmless software; preserve identity/key-custody conditions.',severity='P0')
record('ACC-D5-02','APPROVE WITH REVISION','The HSM/TPM section gives universal validation, throughput and zeroization claims and defines TPM as soldered hardware.','Capabilities vary by module/model/version/mode; TPM measurement and boot enforcement are conflated.','Qualify validation/capabilities and remove generic throughput figures. Describe TPM implementations broadly and separate measurement from enforcement. Use an application request as a configured example, not a universal ban on wrapped export.','An HSM protects sensitive key operations. Its validation, performance and tamper response depend on the exact device and configuration.','HSM ปกป้องการใช้กุญแจสำคัญ การรับรอง ประสิทธิภาพ และการตอบสนองต่อการงัดแงะขึ้นกับอุปกรณ์และการตั้งค่าที่ระบุ','The Yubico model/mode distinction and Microsoft TPM guidance provide direct counterexamples to universal claims.','Do not add detailed FIPS levels or purchasing benchmarks as required CC knowledge; do not imply every HSM is a rack appliance.',severity='P0',refs=['https://docs.yubico.com/hardware/yubihsm-2/hsm-2-user-guide/hsm2-intro-overview.html — model/firmware/mode','https://learn.microsoft.com/en-my/windows/security/hardware-security/tpm/tpm-recommendations — implementation paragraph'])
record('ACC-D5-03','APPROVE WITH REVISION','The section cites Rev.1 as current, treats commands/CE as blanket purge success and says destruction protects 100%.','Revision currency, media/implementation conditions and outcome validation are conflated.','Update the reference and conditional method explanation; retain Clear/Purge/Destroy. Replace certainty with defined recovery infeasibility and verified/validated outcomes; no device-command tutorial.','Choose an approved method for the media and data, verify completion and validate whether sanitization was effective before reuse or disposal.','เลือกวิธีที่ได้รับอนุมัติให้เหมาะกับสื่อและข้อมูล ตรวจว่าดำเนินการเสร็จ และประเมินผลว่าล้างข้อมูลได้ตามเป้าหมายก่อนใช้ซ้ำหรือกำจัด','NIST Rev.2 supersedes Rev.1 and separates verification from validation. A reference-date edit alone would leave incorrect blanket claims.','A drill hole or named erase command does not itself prove successful sanitization; CE needs appropriate key/data conditions.',severity='P0')
record('ACC-D5-04','APPROVE WITH REVISION','The existing six activities and ransomware example are useful, but the introduction attributes that exact ordered sequence to NIST/ISO/ISC2.','Current NIST Rev.3 is a CSF-based model; exact ISO equivalence has not been established.','Relabel the six activities as the course teaching breakdown, clarify iteration and current NIST context. Keep the diagram/activities and case; fix the nonsensical long-term-containment Thai word in the same bounded edit.','These six activities are a teaching breakdown. Current NIST guidance connects incident response with CSF outcomes and continuous improvement.','กิจกรรมทั้งหกเป็นการแบ่งเพื่อการเรียน แนวทาง NIST ปัจจุบันเชื่อมการตอบสนองเหตุการณ์กับผลลัพธ์ CSF และการปรับปรุงต่อเนื่อง','This is an attribution/version correction, not evidence that the six activities are wrong or need wholesale replacement.','Do not merely replace six course activities with the six CSF functions as a new mandatory sequence; no unverified ISO quotation.',severity='P0')
record('ACC-D5-05','APPROVE','PowerShell is labelled T1059 and the graphic uses T1566 for named Spearphishing Link and an unversioned count of 14 tactics.','Named sub-technique IDs and an undated count are inaccurate against the inspected current list.','Use T1059.001 for PowerShell and T1566.002 for Spearphishing Link, or use parent names consistently. Remove the count rather than introduce count memorization.','A tactic describes an adversary goal; a technique describes a way to pursue it. A named sub-technique has its own identifier.','Tactic อธิบายเป้าหมายของผู้โจมตี ส่วน Technique อธิบายวิธีไปสู่เป้าหมาย โดย Sub-technique ที่มีชื่อเฉพาะมีรหัสของตนเอง','Current MITRE pages support the IDs; generic Phishing T1566 and Pass the Hash T1550.002 remain correct.','Keep Why/How distinctions; do not turn ATT&CK into a mandatory linear sequence or require exhaustive IDs.',severity='P1',refs=['https://attack.mitre.org/techniques/T1059/001/','https://attack.mitre.org/techniques/T1566/','https://attack.mitre.org/tactics/enterprise/'])

# The three original non-confirmed leads plus the OT lead retain their own decisions.
record('ACC-D4-01','APPROVE WITH REVISION','The current sentence says supports IPsec; the heading says built-in security.','A beginner could infer automatic protection, but that stronger claim is not actually written.','Add one use/configuration qualification and adjust the heading if necessary. Do not label the entire paragraph a confirmed automatic-encryption error.','IPv6 can use IPsec, but IPv6 addressing alone does not encrypt or authenticate traffic.','IPv6 ใช้ IPsec ได้ แต่การใช้ที่อยู่ IPv6 เพียงอย่างเดียวไม่ได้เข้ารหัสหรือยืนยันความถูกต้องของทราฟฟิก','RFC 8504 sections 13–13.1 support the distinction; this resolves the clarification without inventing a defect.',severity='P2',refs=['https://www.rfc-editor.org/rfc/rfc8504.html#section-13.1'])
record('VER-D1-01','APPROVE WITH REVISION','Line 989 calls for judgment, while line 1057 gives an exceptionless exam conclusion.','The internal contradiction and unsupported certainty are established; an official mechanical canon-conflict algorithm is not.','Replace only the exceptionless/exam-certainty assertion with the existing professional-judgment principle and authorized escalation. Do not assert the opposite hierarchy.','Protect public welfare, preserve relevant evidence and seek appropriate authorized guidance while considering the professional duties in context.','คำนึงถึงสวัสดิภาพสาธารณะ เก็บรักษาหลักฐานที่เกี่ยวข้อง และขอคำแนะนำผ่านช่องทางที่มีอำนาจ โดยพิจารณาหน้าที่ทางวิชาชีพร่วมกับบริบท','The official Code explicitly requires judgment. No new priority algorithm or disclosure instruction is approved.','Keep the four canons; do not infer permission for public disclosure, illegal action or concealment.',severity='P1',refs=['https://www.isc2.org/ethics — Code introduction and canons'])
record('VER-D2-01','HOLD','The fourth scorecard row shows <10 and 12 without units; narration says <10%.','The original unit, denominator and period are not recoverable from the screenshot.','Hold the interpretation of that row. Obtain author clarification or separately approve replacing it with an explicitly hypothetical metric.','The source does not define this row well enough to evaluate it reliably.','ต้นฉบับยังนิยามแถวนี้ไม่เพียงพอให้ประเมินผลได้อย่างเชื่อถือได้','External standards cannot reconstruct missing source units; no silent conversion to count or percent is justified.','The other three percentage rows are usable; preserve them.','Keep 95% versus 91%, including the four-percentage-point gap.',severity='P1',effort='Blocked on source clarification; safe replacement is a separate human choice')

# Explanation decisions: every row includes an illustrative EN/TH sample, even when insertion is rejected.
record('ENR-D1-02','APPROVE WITH REVISION','Worked SLE/ARO/ALE calculations and model limitations already exist; the introduction says formulas must be memorized precisely.','Unsupported exam certainty, not missing arithmetic.','Replace the memorization claim with model/assumption context; retain calculations and add no calculator.','These calculations illustrate a risk estimate using stated assumptions; the result is not a precise prediction of future loss.','การคำนวณนี้แสดงประมาณการความเสี่ยงตามสมมติฐานที่ระบุ ผลลัพธ์ไม่ใช่คำทำนายความเสียหายในอนาคตอย่างแม่นยำ','The outline establishes conceptual risk scope without proving a memorization or frequency claim.')
record('ENR-D1-03','APPROVE WITH REVISION','Identification, authentication and all four rows are already explained; Accounting has allowed/denied activity fields nearby.','The fixed four-stage wording can make three AAA functions appear to be four A functions or logging only the final step.','Clarify the preliminary identity claim and logging throughout relevant attempts; preserve the useful four-row login example.','Identification states a claim. AAA refers to authentication, authorization and accounting; logs may also record failed or denied attempts.','Identification คือการกล่าวอ้างตัวตน ส่วน AAA หมายถึง Authentication, Authorization และ Accounting โดย Log อาจบันทึกความพยายามที่ล้มเหลวหรือถูกปฏิเสธด้วย','This corrects the relationship without another flow or a universal fixed ordering.')
record('ENR-D1-04','APPROVE','The course lists Technical, Managerial, Operational and Physical without relating its labels to official category wording.','Learners need one taxonomy note, not replacement definitions.','Add a short note relating the course subdivision to the outline Technical/Administrative/Physical vocabulary.','The outline names technical, administrative and physical controls; this course also separates managerial and operational activities for explanation.','โครงร่างสอบใช้หมวด Technical, Administrative และ Physical ส่วนบทเรียนนี้แยกกิจกรรม Managerial และ Operational เพิ่มเพื่อช่วยอธิบาย','Useful for terminology alignment; preserve the contextual examples and overlapping functions.',refs=['https://www.isc2.org/certifications/cc/cc-certification-exam-outline — 1.4'])
record('ENR-D1-06','APPROVE WITH REVISION','Risk treatment lists four responses and explains insurance; later risk/conduct sections already supply related context.','Acceptance authority and review conditions are not concrete at the canonical treatment paragraph.','Add two sentences about documented authorized acceptance and review; cross-reference existing criteria and patch/change material rather than repeat it.','Risk acceptance is an informed decision by an authorized owner. Record the remaining risk, reason and conditions for review.','การยอมรับความเสี่ยงเป็นการตัดสินใจโดยผู้มีอำนาจที่ได้รับข้อมูลเพียงพอ ต้องบันทึกความเสี่ยงที่เหลือ เหตุผล และเงื่อนไขทบทวน','This adds decision authority, not another treatment taxonomy.','Do not make the patch installer the risk-acceptance authority or assume a single numeric appetite threshold.')
record('ENR-D2-03','APPROVE','The section covers organizational password policy/storage and phishing-resistant authentication but gives few daily user actions.','A beginner needs the action to take, not more authenticator mechanics.','Add a concise unique-password/password-manager/no-sharing/reporting paragraph; preserve scoped NIST numerical context.','Use a unique password for each account, protect it with an approved password manager and report suspected credential exposure through the organization’s route.','ใช้รหัสผ่านไม่ซ้ำกันในแต่ละบัญชี เก็บด้วย Password Manager ที่องค์กรอนุมัติ และรายงานเมื่อสงสัยว่าข้อมูลยืนยันตัวตนรั่วไหลผ่านช่องทางขององค์กร','Makes the existing organizational controls actionable without another MFA lesson.')
record('ENR-D3-03','APPROVE WITH REVISION','Review findings include a departed-user orphan example and a repeated Finance mover case.','Activity, ownership and applied revocation are different questions.','Clarify that accounts with no accountable owner also need investigation, then distinguish decision, applied change and verification; avoid prescribing a universal definition or idle-day limit.','Recent activity does not prove an account still has an accountable owner. After the review decision, apply the authorized change and verify effective access.','การมีการใช้งานล่าสุดไม่ได้พิสูจน์ว่าบัญชียังมีผู้รับผิดชอบ หลังตัดสินใจทบทวน ต้องปรับตามอำนาจและตรวจสิทธิ์ที่ใช้งานได้จริง','The existing ownership matrix in the published lesson is a strong reuse source; add no new matrix.')
record('ENR-D3-05','REJECT','The prose already names three related functions and contrasts SP 800-63 with CSF. The diagram explicitly says it is not a rigid sequential pipeline.','The claimed sequence gap is already addressed.','Do not append another function explanation or redraw the diagram. Treat the authenticator-control wording precision as a small separately scoped label check, not evidence the diagram needs a new pipeline explanation.','These are related identity functions, not mandatory consecutive stages. (Already conveyed by the current diagram.)','สิ่งเหล่านี้เป็นหน้าที่ด้านตัวตนที่สัมพันธ์กัน ไม่ใช่ขั้นตอนต่อเนื่องที่ทุกระบบต้องทำตามลำดับ (ภาพปัจจุบันสื่อไว้แล้ว)','Rejects a redundant expansion. The sample restates existing meaning and is not approved for insertion.','Do not infer that real-world identity proofing is required for every service.',refs=['js/core/diagram-generator.js:1937–1984 — three interrelated facets and explicit non-sequential caption'])
record('ENR-D3-06','APPROVE','OAuth versus OIDC purposes are already correctly separated, but the OAuth Data Format cell reads JSON / Access Token.','The cell can confuse the JSON token response with the access-token representation.','Change that cell to Access token; format varies. Keep the existing authorization/OIDC contrast and no token internals.','OAuth access tokens can have different formats; a JSON response does not mean the token itself must be JSON or a JWT.','Access Token ของ OAuth มีได้หลายรูปแบบ การตอบกลับเป็น JSON ไม่ได้หมายความว่า Token ต้องเป็น JSON หรือ JWT','RFC 6749 section 1.4 is sufficient for this precise correction.',refs=['https://www.rfc-editor.org/rfc/rfc6749.html#section-1.4'])
record('ENR-D3-08','APPROVE WITH REVISION','The current SoD rule already requires more than one person and gives a three-person payment workflow.','One boundary example can prevent confusing account count with actor independence.','Add one sentence about a person controlling two accounts; do not add another payment table or mandate exactly three people.','Two accounts controlled by one person do not provide independent approval.','บัญชีสองบัญชีที่คนเดียวควบคุมไม่ได้ทำให้การอนุมัติเป็นอิสระจากกัน','A short counterexample clarifies the existing rule without duplicating its scenario.')
record('ENR-D4-02','APPROVE WITH REVISION','The notes already call OSI conceptual and show Data→transport→IP→frame; the published lesson draws nested envelopes.','The phrase headers in each layer and fixed TLS placement need qualification.','Tighten the existing encapsulation caption and approximate-mapping language; reuse the published envelope explanation, not a second ladder.','This is a simplified protocol nesting example; it does not mean every OSI layer adds a separate header.','นี่คือตัวอย่างการซ้อนข้อมูลของโพรโทคอลอย่างย่อ ไม่ได้หมายความว่าทุกชั้น OSI เพิ่ม Header แยกของตนเอง','Preserves the useful mapping while limiting an over-literal reading.',refs=['js/ui/learning/domain4-presentations.js:17–19 — envelope composition'])
record('ENR-D4-03','APPROVE WITH REVISION','The section has a single IP:port example and common-default service table.','A one-way endpoint alone does not show the two transport endpoints; a port number is not proof of a secure session.','Add one declared TCP source/destination flow and a common-defaults caveat. Do not append another ports table or a protocol configuration guide.','Example TCP flow: 192.0.2.10:51514 → 198.51.100.20:443. The port is a service clue; verify the actual protocol and protection.','ตัวอย่าง TCP: 192.0.2.10:51514 → 198.51.100.20:443 หมายเลขพอร์ตเป็นเบาะแสของบริการ ต้องตรวจโพรโทคอลและการป้องกันที่ใช้จริง','Documentation-only addresses and a named transport keep the illustration unambiguous.')
record('ENR-D4-04','APPROVE WITH REVISION','The OT paragraph imposes a universal IT confidentiality priority and an IDMZ/data-diode-only path rule, with detailed Purdue levels.','The guidance is risk- and architecture-dependent; a universal hierarchy/design rule exceeds beginner scope.','Replace categorical priority/path language with process-specific safety/reliability and controlled required communications. Keep Purdue detail optional; no new industrial topology or operational instructions.','For OT, assess safety, reliability and the process impact before changing systems. Permit only required, controlled communications using a suitable architecture.','สำหรับ OT ต้องประเมินความปลอดภัยต่อชีวิต ความเชื่อถือได้ และผลต่อกระบวนการก่อนเปลี่ยนระบบ อนุญาตเฉพาะการสื่อสารที่จำเป็นและควบคุมผ่านสถาปัตยกรรมที่เหมาะสม','NIST 800-82r3 describes alternatives and context, including data diodes as an option; the earlier landing-page-only gap is now narrowed.','Do not approve generic bypass, reboot or patch instructions for a live industrial process.',refs=['https://nvlpubs.nist.gov/nistpubs/SpecialPublications/NIST.SP.800-82r3.pdf — network segregation and unidirectional-gateway discussion'])
record('ENR-D4-06','APPROVE WITH REVISION','Adjacent paragraphs already qualify customer-controlled data/IAM decisions, but table row labels name the whole Data and IAM layers.','The table can be read independently without the necessary service boundary.','Rename the two customer rows to customer-controlled data decisions/settings and IAM decisions/settings; add a service-specific caption. Do not add another responsibility explanation.','This matrix summarizes customer-controlled decisions. The provider remains responsible for the parts of the service it operates; check the selected service and agreement.','ตารางนี้สรุปการตัดสินใจที่ลูกค้าควบคุม ผู้ให้บริการยังรับผิดชอบส่วนบริการที่ตนดำเนินการ ต้องตรวจบริการและข้อตกลงที่เลือก','Moves the already-correct prose caveat into the misleading compact representation.',refs=['https://aws.amazon.com/compliance/shared-responsibility-model/ — applying the model in practice'])
record('ENR-D4-07','APPROVE WITH REVISION','Elasticity already explicitly includes increasing and decreasing resources; measured service is tied directly to pay-as-you-go billing.','Only the mandatory-tariff implication needs a change; a new two-direction scaling example would repeat the text.','Qualify billing as a common use of metering, not the definition of measured service. Preserve the existing scale-up/down explanation.','Measured service means resource use is metered and can be monitored and controlled; the billing arrangement depends on the service.','Measured Service หมายถึงการวัด ติดตาม และควบคุมการใช้ทรัพยากรได้ ส่วนรูปแบบคิดค่าบริการขึ้นกับบริการนั้น','NIST’s definition supports the metering distinction; reject the redundant elasticity expansion.',refs=['https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-145.pdf — essential characteristics'])
record('ENR-D5-08','APPROVE WITH REVISION','The triage text already defines FP/FN and lists context factors, yet says every false negative is most harmful and a suspicious DC login is always P1.','Two absolute study shortcuts override the better contextual explanation.','Replace those absolutes and label the priority matrix illustrative. Reuse existing examples; add no second classifier or matrix.','A missed threat can be serious, but priority depends on the affected asset, evidence, impact and urgency.','ภัยที่ตรวจไม่พบอาจร้ายแรง แต่ลำดับความสำคัญขึ้นกับทรัพย์สินที่ได้รับผล หลักฐาน ผลกระทบ และความเร่งด่วน','This is correction of overgeneralized examples rather than a new triage syllabus.')
record('ENR-D5-12','APPROVE WITH REVISION','The notes list legacy mitigations and categorical EOL/EOS definitions.','The missing piece is an owned, temporary risk decision with a migration/review endpoint.','Add owner, review date and migration decision to the current legacy example; qualify vendor terms and avoid implying isolation restores support.','Temporary controls can reduce exposure while an owner plans replacement; they do not restore vendor support or eliminate the remaining risk.','มาตรการชั่วคราวอาจลดการเผชิญภัยระหว่างที่ผู้รับผิดชอบวางแผนเปลี่ยนระบบ แต่ไม่ได้ทำให้ผู้ผลิตกลับมาสนับสนุนหรือขจัดความเสี่ยงที่เหลือ','Adds a decision boundary to the existing control list, not a new asset-lifecycle wheel.')
record('ENR-D5-13','APPROVE WITH REVISION','The seven-step example already includes testing and post-implementation validation/documentation; CAB approval is stated universally.','Authority and workflow variation need qualification; verification/documentation are not missing wholesale.','Label the seven steps illustrative and CAB one possible authority; retain PIR verification/documentation. Cross-reference the existing baseline/drift section rather than append another process.','Changes need the authority and controls defined by policy. A CAB is one possible review arrangement, not a mandatory committee for every change.','การเปลี่ยนแปลงต้องมีผู้มีอำนาจและมาตรการตามนโยบาย CAB เป็นรูปแบบทบทวนหนึ่ง ไม่ใช่คณะกรรมการบังคับสำหรับทุกการเปลี่ยนแปลง','Avoids the audit’s potential over-expansion of functions the current notes already include.')
record('ENR-D5-14','APPROVE WITH REVISION','Static versus running testing is clear; the table pins each method to a fixed lifecycle phase and calls syntax errors the SAST strength.','Method, timing and findings are conflated.','Keep the existing comparison; state typical early use rather than an exclusive stage, and replace syntax-error wording with security weaknesses in code.','SAST analyzes code without running it; DAST tests a running application. Both can be repeated during development and release work.','SAST วิเคราะห์โค้ดโดยไม่ต้องรัน ส่วน DAST ทดสอบแอปที่กำลังทำงาน ทั้งสองวิธีทำซ้ำได้ระหว่างการพัฒนาและเตรียมเผยแพร่','Clarifies the defining distinction without a new SDLC graphic.')
record('ENR-X-01','APPROVE WITH REVISION','The notes are mainly Thai explanations with English terminology; published lessons have fuller bilingual explanations.','Approval of a few edits must not silently authorize translation of all five books.','Make semantic EN/TH parity an acceptance criterion for approved changed passages only; scope a full English edition separately.','For each approved edit, both languages must preserve the same actor, condition, quantity and limitation.','ในการแก้ไขที่อนุมัติ แต่ละภาษาต้องคงผู้กระทำ เงื่อนไข ปริมาณ และข้อจำกัดเดียวกัน','Approve bounded bilingual review, not an uncontrolled full-course rewrite.','No blanket translation or restructuring of unchanged chapters is authorized by this proposal.',effort='15–30 minutes per approved passage; full translation is not estimated or approved')
record('ENR-X-02','APPROVE WITH REVISION','Published AI/PQC examples are richer than the notes; the current outline includes foundational applications.','Reading learners need a compact application, not a repeated AI mini-course or crypto mathematics.','Place one short PQC paragraph in D5 cryptography and selectively adapt existing AI examples at their canonical concepts; no per-domain quota or new asset suite.','Some public-key methods face quantum-computing threats. A KEM establishes a shared secret for later use; it is not the same operation as bulk-data encryption.','วิธีกุญแจสาธารณะบางชนิดเผชิญภัยจากคอมพิวเตอร์ควอนตัม KEM ใช้สร้างความลับร่วมสำหรับนำไปใช้ต่อ ไม่ใช่การเข้ารหัสข้อมูลจำนวนมากโดยตัวมันเอง','Use the applicable outline and already-reviewed slide examples. Distinguish essential concepts from optional implementation detail.','No quantum deadline, algorithm-parameter memorization or AI-vendor safety promise.',refs=['https://csrc.nist.gov/pubs/fips/203/final — KEM purpose'],effort='1–2 hours for compact scoped applications and bilingual/source checks')

# Practical examples: approve the distinct decision, not an additional scenario quota.
record('ENR-D1-05','APPROVE WITH REVISION','The same subsection already allows reading and denies deleting, then lists Who/What/When/Where/outcome fields.','It has no visible log record joining that decision to the evidence.','Add one log row for the existing denied-delete action; reuse its actor/resource rather than introduce a separate order-approval story.','10:04 | account A | delete system file | denied — this records the attempt, not permission to delete.','10:04 | บัญชี A | ลบไฟล์ระบบ | ปฏิเสธ — บันทึกนี้แสดงความพยายาม ไม่ใช่สิทธิ์ให้ลบ','One record makes accounting tangible without another AAA definition.','Fictional account/resource, explicit example time zone if timestamps are compared; a log does not alone identify the physical person.')
record('ENR-D2-04','APPROVE WITH REVISION','Five GRC platform capabilities are listed; the next subsection already has a substantial risk register.','The relationship among requirement, control, evidence and responsible owner is not shown as a linked record.','Use one compact authored record, not another risk register: policy requirement→MFA control→dated evidence→owner/review.','Requirement: protect privileged access. Control: approved MFA policy. Evidence: dated assessment. Owner: IAM lead; review due on the stated date.','ข้อกำหนด: ปกป้องสิทธิ์ระดับสูง มาตรการ: นโยบาย MFA ที่อนุมัติ หลักฐาน: ผลประเมินที่ลงวันที่ ผู้รับผิดชอบ: หัวหน้า IAM พร้อมวันทบทวนที่ระบุ','Demonstrates evidence linkage rather than repeating the existing ransomware register.','Illustrative organizational requirement, not a universal regulation; do not promise a GRC tool makes compliance automatic.')
record('ENR-D2-05','APPROVE WITH REVISION','BCP lists critical processes, roles, communications and alternates; BC/DR comparisons elsewhere are already present.','The learner has not seen those fields form a miniature operational continuity plan.','Adapt a two-to-four-line hypothetical plan showing minimum service, approved workaround, owner and contact route; no full corporate template.','During a site outage, the designated service lead uses the approved alternate process to maintain the defined minimum service and informs staff through the agreed channel.','เมื่อสถานที่หลักหยุดใช้งาน ผู้รับผิดชอบบริการใช้กระบวนการสำรองที่อนุมัติเพื่อคงบริการขั้นต่ำที่กำหนด และแจ้งทีมผ่านช่องทางที่ตกลงไว้','Adds recognition of a plan rather than another definition of continuity.','No unsafe medical/industrial instructions or real contact details; state the scenario is illustrative.')
record('ENR-D2-06','APPROVE','MTTR endpoints and alternative expansions are already qualified; no worked average appears in the target subsection.','A beginner needs to connect defined intervals with a numerical mean.','Add a single three-case calculation and the same-population/time-boundary caveat; no timing widget.','For three incidents measured using the same detection endpoints, 10, 20 and 30 minutes average to 20 minutes. This mean does not describe incidents that were never detected.','เหตุการณ์สามกรณีที่ใช้จุดเริ่มและจุดสิ้นสุดการตรวจพบเดียวกัน ใช้เวลา 10, 20 และ 30 นาที จึงเฉลี่ย 20 นาที ค่าเฉลี่ยนี้ไม่ได้อธิบายเหตุการณ์ที่ยังตรวจไม่พบ','The arithmetic is simple and the outcome teaches measurement boundaries, not memorized thresholds.')
record('ENR-D3-02','APPROVE','Provisioning already requires role need and approval, then lists six illustrative activities.','Approval and effective enforcement can still differ; there is no observed-versus-approved test result.','Adapt the existing published three-action check as one compact comparison: report read allowed, payroll change denied, unrelated administration denied; correct the observed mismatch.','Approved: read the report. Observed: payroll modification also succeeds. Correct the unintended grant and verify both allowed and denied actions again.','สิทธิ์ที่อนุมัติคืออ่านรายงาน แต่ผลตรวจพบว่าแก้ Payroll ได้ด้วย ต้องแก้สิทธิ์ที่เกินและตรวจซ้ำทั้งงานที่อนุญาตและงานที่ต้องปฏิเสธ','The example adds verification, not another onboarding sequence.','Use synthetic roles and explicitly approved actions; do not infer HR alone approves every resource permission.')
record('ENR-D3-04','APPROVE','The notes separately list central disable, app revocation and group/privileged removal, with a careful retention caveat.','A concrete surviving session explains why these are separate actions.','Adapt the published observed-session case and one denial check; no token/configuration tutorial.','The central account is disabled, but an existing application session still works in this example. Use the supported revocation process and verify the application denies access.','ในตัวอย่างนี้บัญชีกลางถูกระงับแล้ว แต่ Session เดิมในแอปยังใช้ได้ จึงต้องใช้กระบวนการเพิกถอนที่ระบบรองรับและตรวจว่าแอปปฏิเสธการเข้าถึง','A realistic bounded observation explains coordinated withdrawal without claiming every application behaves identically.')
record('ENR-D3-07','APPROVE WITH REVISION','Least privilege already explicitly includes service accounts and programs, with role-scoped access and reviews.','Non-human identity ownership and retirement are not concrete in the reading example.','Adapt one read-only reporting workload case and name its accountable team/review trigger; no separate bot chapter or human MFA rule.','The reporting workload may read only the approved report source. Its owner reviews the purpose and retires the identity when the job ends.','ระบบงานรายงานอ่านได้เฉพาะแหล่งข้อมูลที่อนุมัติ ผู้รับผิดชอบทบทวนวัตถุประสงค์และเลิกใช้ Identity เมื่องานสิ้นสุด','The gap is lifecycle accountability, not whether least privilege applies to software.','Do not prescribe interactive human authentication for unattended workloads.')
record('ENR-D4-05','APPROVE WITH REVISION','VLAN separation and inter-VLAN Layer 3 enforcement are already explained; review scenarios already discuss IoT separation.','The allowed legitimate flow versus denied sensitive flow is the useful addition.','Add a two-row camera→recorder allow / camera→database deny policy test at the existing VLAN paragraph, or replace a generic IoT example rather than append another scenario.','Permit the camera to send its required stream to the recorder; deny the camera’s unrelated path to the finance database and verify both results.','อนุญาตให้กล้องส่งสตรีมที่จำเป็นไปยังเครื่องบันทึก ปฏิเสธเส้นทางที่ไม่เกี่ยวข้องไปฐานข้อมูลการเงิน และตรวจผลทั้งสองกรณี','Adds enforcement reasoning while preserving the current VLAN definition and existing segmentation picture.',deps=['ACC-D4-03'])
record('ENR-D5-06','APPROVE WITH REVISION','Three data states already have definitions, threats, controls and a summary table; a lost-laptop scenario appears later.','The transitions of the same record and authorized export boundary are not connected.','Use one short record journey through storage, TLS and authorized display/export. Select one AI/DLP extension if it replaces repetition; no extra state cards.','A customer record is stored encrypted, sent through TLS and displayed by an authorized application. These controls do not authorize copying it into an unapproved external service.','ข้อมูลลูกค้าถูกเก็บแบบเข้ารหัส ส่งผ่าน TLS และแสดงในแอปที่ได้รับอนุญาต มาตรการเหล่านี้ไม่ได้อนุญาตให้นำข้อมูลไปใส่บริการภายนอกที่ไม่ได้รับอนุมัติ','The same record connects mechanisms with use authority; another three-state definition would be redundant.','Do not promise FDE/TLS protects against every authorized-session exposure or that DLP sees every encrypted channel.')
record('ENR-D5-07','APPROVE WITH REVISION','An existing four-event chain immediately concludes successful brute force and code compromise; the chapter already has a logging-field list.','The chain lacks explicit identity/time linkage and alternative explanations; certainty is too strong.','Replace the conclusion and add minimal timestamps/account/host linkage to the existing chain, not another chain. State that analysts validate the hypothesis and response priority.','Related failed logins, a later success and a script alert warrant investigation. Confirm the account, host, time zone and authorized activity before concluding compromise.','การล็อกอินล้มเหลวที่สัมพันธ์กัน ตามด้วยการสำเร็จและ Alert สคริปต์ควรได้รับการตรวจสอบ ต้องยืนยันบัญชี โฮสต์ เขตเวลา และกิจกรรมที่ได้รับอนุญาตก่อนสรุปว่าถูกบุกรุก','This package is partly a confidence/overstatement correction, not just an additional example.','An alert/correlation is not proof; preserve originals and do not invent a mandatory severity from one signal.')
record('ENR-D5-10','APPROVE WITH REVISION','Custody prose already names collector, place, time, recipient and purpose; hash/image explanations are present.','A single filled handoff demonstrates the fields; the surrounding court/power/volatility absolutes need restraint.','Add a synthetic one-line handoff and a hash-versus-custody distinction; qualify operational/legal statements rather than prescribe evidence collection steps.','Evidence E-17: transferred from examiner A to custodian B at 10:00 UTC for secured storage; both acknowledge the transfer. A matching hash alone does not supply this custody history.','หลักฐาน E-17 ส่งจากผู้ตรวจ A ให้ผู้ดูแล B เวลา 10:00 UTC เพื่อเก็บอย่างปลอดภัย โดยทั้งคู่รับทราบ การมี Hash ตรงกันเพียงอย่างเดียวไม่ได้ให้ประวัติการส่งมอบนี้','Teaches a record with a clear purpose; no forensic tutorial or admissibility guarantee is needed.','Follow trained authorized procedures and safety/active-harm priorities; no universal shutdown or court-rejection instruction.')
record('ENR-D5-11','APPROVE WITH REVISION','Exercise comparison and the earlier IR recovery example already describe testing and restoration.','The distinct missing artifact is an observed exercise result and owned follow-up.','Use one compact restore-test result with expected outcome, actual application result, gap owner and retest. Do not add another tabletop/technical comparison or fixed exercise frequency.','The isolated restore completed, but the application could not read two expected records. Assign an owner to resolve the gap and repeat the defined test.','การกู้คืนในระบบแยกเสร็จแล้ว แต่แอปอ่านข้อมูลที่คาดไว้สองรายการไม่ได้ ต้องมอบหมายผู้รับผิดชอบแก้ช่องว่างและทดสอบตามเกณฑ์เดิมอีกครั้ง','This tests usable recovery rather than repeating backup-job completion.','Fictional result, approved isolated environment and defined scope; no zero-risk promise.')
record('ENR-D5-15','APPROVE','Threat modeling is defined and STRIDE categories are listed, but there is no single evaluated boundary/control/test example.','A concrete request path can connect the abstract analysis to a design decision.','Add one account-recovery request case with the untrusted request, server-side verification, limited reset action and a denial test; no exploit instructions or six-category tour.','An untrusted recovery request must not reset another account. Verify the authorized recovery evidence server-side, limit the reset action, and test that an invalid request is denied.','คำขอกู้บัญชีที่ไม่น่าเชื่อถือต้องรีเซ็ตบัญชีผู้อื่นไม่ได้ ให้ตรวจหลักฐานกู้บัญชีที่อนุญาตบนเซิร์ฟเวอร์ จำกัดการรีเซ็ต และทดสอบว่าคำขอไม่ถูกต้องถูกปฏิเสธ','The example follows the existing published threat-modeling goal while adding one evaluated request boundary.','Do not claim MFA alone solves recovery design or that threat modeling ends when coding starts.')

# New-media candidates. Existing equivalents and dependencies are evaluated individually.
record('VIS-01','APPROVE WITH REVISION','Reading Notes have IDS/IPS text; the published lesson has a function/limitation comparison, not paired physical traffic paths.','Traffic-copy observation versus in-path enforcement remains a distinct visual relationship.','Use one compact paired static topology with client/server, switch mirror/TAP→IDS→alert, and client→IPS→server with prevention enabled. Reuse existing wording; no product UI.',reason='A placement picture can teach what a function table cannot. It should not grow into another device taxonomy.',constraints='Label traffic versus copied traffic and alert; a passive sensor does not directly block that path, and a configured IPS can miss/allow traffic.',deps=['ACC-D4-03'],effort='2–3 hours for one static bilingual responsive diagram and targeted QA')
record('VIS-02','APPROVE WITH REVISION','The TPM/HSM table and published signature-custody comparison explain functions; neither shows the requested application/HSM protection boundary.','A learner cannot yet see that a request/output crosses the boundary while the configured private key stays inside.','Use one static application→authorized signing request→HSM boundary/private key→signature response, with concise verifier text outside. Do not combine an extra generic encryption track.',reason='Different from a physical photo: it teaches key custody and operation flow.',constraints='Explicit non-exportable-key example; wrapped backup/export policies vary. No private-key movement, generic public-key decryption or signed-means-safe promise.',deps=['ACC-D5-01','ACC-D5-02'],effort='2–3 hours after crypto/hardware corrections')
record('D2-A01','APPROVE WITH REVISION','The target already has a full/differential/incremental table and Thursday failure/Sunday full worked set; the slide shows copy/verify/restore/test.','A compact set-dependency picture can make the restore-chain dependency visible without new arithmetic.','Adapt the existing Sunday/Wednesday/Thursday example. State the incident occurs before Thursday’s next backup; highlight full+latest differential versus full+all required incrementals.',reason='Distinct visual encoding of existing set relationships, not another recovery timeline.',constraints='Conventional simplified backup model; label valid accessible restore sets and no universal speed/storage guarantee.',deps=['ACC-D2-01'],effort='1.5–2.5 hours for the compact diagram and bilingual equivalent')
record('D2-A02','APPROVE WITH REVISION','The notes and published lesson teach pressure, request and independent verification, but no inspectable message interface is present.','Message-interface recognition can add value if it demonstrates the requested action and safe verification route.','Choose an original clearly labelled simulated HTML message with adjacent annotations, rather than a licensed-real screenshot dependency or rasterized text.',reason='An authored interface avoids unresolved third-party image rights and supports readable responsive text.',constraints='No live links, real PII, copied trademarks or grammar-as-proof heuristic; report and independently verify. Original raster/AI illustration is optional only if it adds value beyond accessible HTML.',effort='1.5–2.5 hours; real external-photo variant is not approved')
record('D4-M01','REJECT','Published slide-d4-01-05-encapsulation already renders nested frame/IP/transport envelopes through the custom envelope branch.','A new diagram would duplicate an existing code-native visual.','Link/adapt the existing learning explanation within ENR-D4-02; do not create a second asset.',reason='The reuse gate is satisfied by actual renderer source, not merely a title or keyword match.',refs=['js/ui/learning/domain4-presentations.js:17–19','content/isc2-cc-2026/learning/published/lessons/lesson-d4-01-network-request.json#slide-d4-01-05-encapsulation'],effort='No new asset work')
