def esc(x):return str(x).replace('|','\\|').replace('\n','<br>')
def target_text(r):return '; '.join(f"`{t['path']}:{t.get('startLine','section')}` — `{t['anchor']}`" for t in r['targets'])
def refs_text(r):
    parts=[]
    for s in r['supportingSources']:
        match=re.search(r'https?://[^\s]+',s)
        parts.append(f"[{esc(s.split(' — ')[-1] if ' — ' in s else 'Primary reference')}]({match.group(0)})" if match else esc(s))
    return '; '.join(parts)
def details(r,sample=True):
    out=[f"### {r['id']} — {r['decision']}",f"Domain {r['domain']}; objective {r['officialObjective']}; severity {r['severity']}. Target: {target_text(r)}.",f"**Current coverage:** {r['currentLearnerExperience']}",f"**Gap / judgment:** {r['genuineGap']} {r['reason']}",f"**Smallest useful change:** {r['smallestUsefulChange']}",f"**Constraints:** {r['academicConstraints']} **Preserve:** {r['preserveExisting']}"]
    if sample and r['sample']['en']:out += ['**EN sample:** '+r['sample']['en'],'**TH sample:** '+r['sample']['th']]
    out += ['**Evidence:** '+refs_text(r),f"**Dependencies:** {', '.join(r['dependencies']) or 'None'}. **Effort:** {r['estimatedEffort']}."]
    return '\n\n'.join(out)
